/**
 * parser/: Oracle text -> ability model. Pure, deterministic, no I/O, runs in the engine package (browser and Node). Owners: WP5 (front end),
 * WP6 (chart parser, hole grammars), WP17 (lowering, anaphora, taint, parseCard), WP19-WP23 (template data).
 *
 * Files:
 *   parser/types.ts                this file
 *   parser/lexicon.generated.json  GENERATED by scripts/gen-lexicon.ts from rules/cr/ (+ the local Oracle index for card-type words); a test fails if stale
 *   parser/preprocess.ts           normalize, reminder text, self reference "~", labels, ability words
 *   parser/segment.ts              lines -> abilities (classification) -> sentences; modal bullets, chapters, levels, dice rows, spree
 *   parser/tokenize.ts             tokens (WORD NUM X MANA TAP PT MOD ROMAN SELF PUNCT BULLET QUOTE ERR)
 *   parser/chart.ts                Earley chart parser over tokens, whole-derivation ambiguity detection, node budget (WP6)
 *   parser/holes/{filter,object,player,qty,cost,cond,dur,event,token,zone,misc}.ts   typed hole grammars (code)
 *   parser/templates/{cost,trigger,condition,duration,keyword,static,ability}.json, parser/templates/effect/*.json   template data (WP19-WP23)
 *   parser/lower/{targets,anaphora,riders,quantities,durations,conditions,optionality,sequencing,normalize}.ts   lowering passes (WP17)
 *   parser/taint.ts                contagion / poisoning / look-ahead taint (design 6.7)
 *   parser/parse.ts                parseCard (never throws)
 *   parser/metrics.ts              out-of-sample retention, ambiguity list, residue clustering (used by the coverage CLI)
 */
import type { AbilityDef, ActivatedAbilityDef, Condition } from '../types/ability';
import type { OracleCard } from '../types/card';
import type { GateResult } from '../render/api';

/** Pattern DSL (design 6.3): WORD, {name:Type}, [optional], (a|b), ~, word[s]/word[es], ^ sentence start. */
export type HoleType =
  | 'Qty' | 'Count' | 'Obj' | 'Objs' | 'Player' | 'Recipient' | 'Filter' | 'Cost' | 'Cond' | 'Dur' | 'Event' | 'Color' | 'Zone'
  | 'CounterKind' | 'ManaCost' | 'PT' | 'Keyword' | 'TokenDesc' | 'ChoiceKind' | 'Effects' | 'Text' | 'Abilities' | 'Name' | 'Lib'
  /** WP22 ADDITION (INTERFACE CHANGE): printed, unsigned power/toughness ("base power and toughness 3/3", "becomes a 2/2 creature"), value {p, t}. */
  | 'BasePT'
  /** WP22 ADDITION (INTERFACE CHANGE): a run of singular subtype words in a type description ("a green Elk creature"), value string[] (CR 205.3). */
  | 'Subtypes'
  /**
   * std-tla ADDITION (INTERFACE CHANGE): the words "milled this way" after a card noun phrase ("You may put a land card milled this way into your hand"): the cards a
   * `mill` step of an earlier sentence put into a graveyard, the same plural anaphor as `Milled`'s "the milled cards" (parser/holes/object.ts#milledThisWay; CR 701.17a, 608.2c).
   */
  | 'MilledThisWay'
  /**
   * std-ro ADDITION (INTERFACE CHANGE): the words "revealed this way" after a card noun phrase ("Put all land cards revealed this way into your hand"): the top cards of a
   * library a `reveal` step of an earlier sentence revealed, still in that library (parser/holes/object.ts#revealedThisWay; CR 701.20a, 608.2c).
   */
  | 'RevealedThisWay'
  /**
   * PUSH1 T2 ADDITION (INTERFACE CHANGE): ONE target that may be an object or a player: "any target" (CR 115.4), "target creature or player", "target player
   * or planeswalker"; value: the target reference. The Recipient hole reads these and also every object and player phrase, so a template that must tell
   * "any target" from "target creature" uses this one.
   */
  | 'AnyTarget'
  /** FAST1 T4 ADDITION (INTERFACE CHANGE): the mana an instruction adds, value `ManaType[][]` as `addMana.units` ("{B}{G}", "{W}, {U}, or {B}"; parser/holes/misc.ts). */
  | 'ManaUnits'
  /** FAST2 T7 ADDITION (INTERFACE CHANGE): one one-type mana symbol alone, value `ManaType` ("Add {G} for each creature you control"; parser/holes/misc.ts). */
  | 'ManaSym'
  /**
   * FAST3 T18 ADDITION (INTERFACE CHANGE): a group named earlier and nothing else, "them" or "those creatures" (the plural anaphors of `Objs`), so a template can
   * say "on each of them" without also reading "each of" in front of a target phrase (parser/holes/object.ts#group).
   */
  | 'Group'
  /**
   * MX2 ADDITION (INTERFACE CHANGE): exactly two objects named by ONE target phrase, "two target creatures", "two other target artifacts" (one target spec
   * with two targets, CR 115.1, 601.2c), never a list of two phrases (parser/holes/object.ts#pair): "exchange control of two target creatures".
   */
  | 'Pair'
  /**
   * FAST5 T66 ADDITION (INTERFACE CHANGE): ONE target phrase "up to one target nonland permanent that player controls" for a sentence that starts "for each opponent,": a target
   * for each opponent, controlled by that opponent (one target spec whose targets are at most one per opponent, CR 115.1, 601.2c; `TargetSpec.perOpponent`; parser/holes/object.ts#oppTarget).
   */
  | 'OppTarget'
  | 'PlayerTarget' // r5-fxb: as OppTarget, after "for each player," (TargetSpec.perPlayer)
  /**
   * FAST5 T47 ADDITION (INTERFACE CHANGE): the contraction "it's" as the pronoun it stands for, an object named earlier, one anaphor like `Obj`'s "it"
   * ("Return it to the battlefield. It's an enchantment."): the tokenizer keeps "it's" as one word, which `Obj` does not read (parser/holes/object.ts#itIs).
   */
  | 'ItIs'
  /**
   * FAST4 T34 ADDITION (INTERFACE CHANGE): the further recipients of divided-free damage named after a first target, "each of up to two other targets" (ONE
   * target spec of any targets, CR 115.4, with up to N targets that must differ from the targets named before it, CR 115.3; parser/holes/object.ts#otherTargets).
   */
  | 'OtherTargets'
  /**
   * FAST5X E23 ADDITION (INTERFACE CHANGE): a mana spending restriction after "spend this mana only to" (CR 106.6), value `ManaRestriction`; and the spells
   * "this mana can't be spent to cast", value `ObjectFilter` (parser/holes/spend.ts).
   */
  | 'ManaSpend' | 'SpellsCast'
  /**
   * FAST5 T42 ADDITION (INTERFACE CHANGE): only a TARGET phrase ("target Equipment card from your graveyard", "up to two target creatures"), never `~`, a pronoun or a
   * set of objects (parser/holes/object.ts#targetPhrases): for a template whose other hole would otherwise accept an unbound reference to the source after it moved.
   */
  | 'Targets'
  /**
   * FAST5 T46 ADDITION (INTERFACE CHANGE): "<description> card from it", the cards of a hand an earlier sentence revealed or looked at ("You choose a nonland card from
   * it", CR 701.20a, 701.20e), value `{ref:'each', filter}` over the anaphor `hand` (parser/holes/object.ts#handCard); only that hand's mention answers to it.
   */
  | 'HandCard'
  /** FAST5 T46 ADDITION (INTERFACE CHANGE): "that card" naming the card a `chooseObjects` step chose (CR 608.2c; parser/holes/object.ts#chosenCard), an anaphor with the participle `chosen`. */
  | 'ChosenCard'
  /**
   * CLOUD C5 ADDITION (INTERFACE CHANGE): "of the chosen color", "of the chosen type" (and the other kinds of parser/holes/filter.ts#CHOSEN) where the template, not
   * the noun phrase, places it ("Spells you cast of the chosen type cost {1} less to cast"): the value is the `chosen` field of a filter, `{link:'$link', quality}`,
   * resolved by parser/lower/links.ts like the Filter hole's own (CR 607.2d).
   */
  | 'Chosen'
  /**
   * FAST5 T43 ADDITION (INTERFACE CHANGE): "the rest" or "the other" of a group after a choice among it, and nothing else: a plural anaphor with the head noun
   * "rest" (parser/holes/object.ts#rest, lower/mentions.ts#restOf), so a template can say "put the rest on the bottom of your library".
   */
  | 'Rest'
  /**
   * FAST5 T43 ADDITION (INTERFACE CHANGE): "them" or "those cards" for the cards of a library a player looked at or revealed, and nothing else: a plural anaphor
   * whose antecedent must be such a group (the participle "seen" of lower/mentions.ts), never cards a mill, a search or an exile put elsewhere
   * (parser/holes/object.ts#seen).
   */
  | 'Seen'
  /**
   * FAST5 T45 ADDITION (INTERFACE CHANGE): the description of a spell that is cast, without its article, as the `spell` filter of a `cast` event pattern
   * ("instant or sorcery spell with mana value 3 or less", "outlaw spell"): the noun phrase the Event hole reads after "cast a", with no `zone` and no
   * `stackKind` (the cast event is about the spell being put on the stack; parser/holes/event.ts#castSpell).
   */
  | 'CastSpell'
  /**
   * FAST5 T49 ADDITION (INTERFACE CHANGE): the word "they" as the subject that names a plural group an earlier sentence named ("They each deal damage equal to
   * their power to ..."): the plural anaphor of `Objs` (sort `set`), resolved by the unique-candidate rule (design 6.4; parser/holes/object.ts#they).
   */
  | 'They'
  /**
   * FAST5 T76 ADDITION (INTERFACE CHANGE): a plural anaphor that is not a subject, "them" or "those <plural noun>" ("untap them", "untap those creatures",
   * "sacrifice them"): only the pronoun readings of `Objs` (sort `set`, resolved by the unique-candidate rule and the focus rule, design 6.4;
   * parser/holes/object.ts#them), never a target or a described group.
   */
  | 'Them'
  /**
   * r3-dig ADDITION (INTERFACE CHANGE): "those <card type> cards" ("Put those land cards onto the battlefield tapped"), the plural anaphor of a group of cards an
   * earlier instruction named by that type (the cards "reveal ... until you reveal two land cards" stopped at): head the type, resolved by the unique-candidate rule
   * (design 6.4; parser/holes/object.ts#typedThose). Only one card type word and "cards".
   */
  | 'TypedThose'
  /**
   * FAST5X E21 ADDITION (INTERFACE CHANGE): the object whose counters are put on another object, "its counters", "those counters", "~'s counters" (CR 122.5,
   * 122.8; parser/holes/object.ts#countersOf): its value is an object reference.
   */
  | 'CountersOf'
  /** M12-3 ADDITION (INTERFACE CHANGE), CR 701.38b: the two words of a vote, "carnage or homage" (a closed list, parser/holes/vote.ts), value string[]. */
  | 'VoteWords'
  /**
   * T55 ADDITION (INTERFACE CHANGE): a token that is given its name first, "Mowu, a legendary 3/3 green Dog creature token", "The Void, a legendary 5/5 black Horror
   * Villain creature token with flying and \"The Void attacks each combat if able.\"" (CR 111.4); value: the `TokenDef` with its `name` (parser/holes/token.ts#namedToken).
   */
  | 'NamedToken'
  /**
   * FAST5 T56 ADDITION (INTERFACE CHANGE): "a creature card", "an instant or sorcery card", "a creature card with flying", the card description after "discard" (article
   * included), value the `discard` cost part's filter (no `isCard`, no `zone`; `{}` for "a card"), so "unless you discard an artifact card" is a cost the payer chooses a
   * matching hand card for (parser/holes/cost.ts#discardDesc, CR 701.9a, 118.12).
   */
  | 'DiscardDesc'
  /**
   * FAST5 T60 ADDITION (INTERFACE CHANGE): one plural card type word ("lands", "artifacts"), value the type names (string[]), what a type-adding static ability adds
   * ("are lands in addition to their other types", CR 205.1b; parser/holes/misc.ts#cardTypes).
   */
  | 'CardTypes'
  /**
   * FAST5 T70 ADDITION (INTERFACE CHANGE): the card (`Impulse`: "it", "that card") or the cards (`Impulses`: "them", "those cards") an earlier instruction of the
   * ability exiled from the top of a library ("Exile the top two cards of your library. You may play those cards this turn", CR 611.2c, 400.7), and nothing else:
   * an anaphor with `impulse: true`, which the unique-candidate rule never resolves (lower/anaphora.ts#compatible); only the impulse idiom
   * (lower/anaphora.ts#impulseIdiom) binds it, and a sentence it cannot bind stays manual (parser/holes/object.ts#impulse).
   */
  | 'Impulse' | 'Impulses'
  /**
   * FAST5 T75 ADDITION (INTERFACE CHANGE): "them" or "those cards" for the cards an earlier sentence's `mill` (`Milled`, now in a graveyard) or `search` (`Found`, still in
   * the library) step produced, and nothing else: a plural anaphor with the participle `milled` / `found`, which only that step's mention (lower/mentions.ts)
   * answers (parser/holes/object.ts#milled, #found).
   */
  | 'Milled' | 'Found'
  /**
   * Cloud std-dsk ADDITION (INTERFACE CHANGE): one LISTED counter kind of a list to choose from ("a flying, lifelink, or +1/+1 counter"), no "counter" needed right
   * after it, value the kind (parser/holes/stddsk.ts#listedCounterKind; CR 122.1b, 608.2d).
   */
  | 'ListedCounterKind'
  /** Cloud std-dsk ADDITION (INTERFACE CHANGE): a card description with "that doesn't have the same name as <a described object>", value the filter (parser/holes/stddsk.ts#notSameNameCard; CR 201.2). */
  | 'NotSameNameCard'
  /** C6 ADDITION: "opponent who can't" / "player who can't" after "for each": the players of a group who can't do what an earlier instruction told them (holes/player.ts#whoCant). */
  | 'WhoCant'
  /** Cloud r3-mech ADDITION (INTERFACE CHANGE): a Siege's choice word ("choose Abzan or Mardu"), a closed list, value the word (parser/holes/r3mech.ts#siegeWord; CR 614.12a). */
  | 'SiegeWord'
  | 'PluralSubtype' // cloud r4-mech
  | 'NotMoved' // r4-moved (parser/holes/moved.ts#notMoved)
  /** Cloud r4-dig ADDITION (INTERFACE CHANGE): a plural card description with no count ("creature and/or land cards"), parser/holes/r4dig.ts#cardsDesc. */
  | 'CardsDesc'
  /** Cloud r4-dig ADDITION (INTERFACE CHANGE): the card a library search is for, ranked one unspecific word lower (parser/holes/r4dig.ts#searchDesc). */
  | 'SearchDesc'
  /** r5-moved ADDITION (INTERFACE CHANGE): "a <card>" before "into your graveyard this way" after a surveil 1: one card description with no zone of its own, value the filter (parser/holes/moved.ts#surveilledCard; CR 701.25a). */
  | 'SurveilledCard'
  /** r5-moved ADDITION (INTERFACE CHANGE): "a <permanent> returned this way" after "for each opponent who controlled": that opponent controlled one of what the return right before moved, value the condition (parser/holes/moved.ts#controlledMoved; CR 608.2h). */
  | 'ControlledMoved'
  /** r5-fxz ADDITION: "card you put on top of your library" after "for each": the count of the cards an earlier surveil or scry left on top (holes/r5fxz.ts#keptOnTop). */
  | 'KeptOnTop'
  /** std-rD ADDITION: "artifact or enchantment", "artifact, creature, or land": the card types a choice offers (parser/holes/misc.ts#typeChoices; CR 205.2a). */
  | 'TypeChoices'
  | 'CardDesc' // std-exile-play-2-3: parser/holes/sxp23.ts
  /**
   * std-mana-12 ADDITION: a mana cost with at least one symbol that is not generic ("{W}{U}{B}{R}{G}", "{1}{G}"), value the symbols as `ManaCost` gives them
   * (parser/holes/misc.ts#coloredManaCost): for a template that must not read a generic-only cost another template reads ("cost {3} less").
   */
  | 'ColoredManaCost'
  /** std-combat-5 ADDITION: "Human, Merfolk, or Goblin": the creature types a choice offers (parser/holes/stdcombat5.ts#creatureTypeChoices; CR 205.3m). */
  | 'CreatureTypeChoices'
  /** p2-replace-damage-2 ADDITION: "<source> would deal [combat] damage to <recipient>", value the replaced damage event pattern (parser/holes/p2rd2.ts#damageWould; CR 614.1a, 120.3). */
  | 'DamageWould' | 'DamageMore' // p2-replace-damage-2: DamageMore, "double that damage", "that much damage plus N" [to that ...] (parser/holes/p2rd2.ts#damageMore)
  /** std-combat-5 ADDITION: "the chosen type" on its own (after "is"): the `chosen` value of a filter with the link placeholder (parser/holes/stdcombat5.ts#chosenType; CR 607.2d). */
  | 'ChosenType'
  /** p2-copy-perm-1 ADDITION: the exceptions of a copy, "it isn't legendary, is a Spirit in addition to its other types, and has haste" (parser/holes/p2copyperm1.ts; CR 707.9b). */
  | 'CopyExcept'
  /** p2-copy-perm-1 ADDITION: the same, said of one token ("the token isn't legendary"). */
  | 'CopyExceptToken'
  /** p2-copy-perm-1 ADDITION: the same, said of several tokens ("they're 3/3 Dragon creatures in addition to their other types, and they have flying"). */
  | 'CopyExceptTokens'
  /** p2-counters-state-1 ADDITION: "~ was kicked with its {1}{R} kicker" (CR 702.33f), value a `wasCast` condition with a kicker marker (parser/holes/p2cs1.ts). */
  | 'KickedWith'
  /** p2-replace-events-1 ADDITION: the rest of a sentence read as one complete static ability of replacement effects (parser/holes/p2re1.ts#replStatic; CR 614.1a, 611.2a). */
  | 'ReplStatic';

export type TemplateKind = 'ability' | 'cost' | 'trigger' | 'condition' | 'effect' | 'static' | 'filter' | 'quantity' | 'duration' | 'event' | 'rider';

export interface TemplateExample {
  /** Minimal or synthetic wording (invented numbers/names), NOT verbatim card text: committed templates must not carry Wizards text (design 6.10). */
  text: string;
  /** JSON the example must lower to; omitted = "must parse, render identically and pass the gate". */
  expect?: unknown;
}

/** A bidirectional text pattern. Pure data: it ships in rules packs (examples are stripped from packs). */
export interface Template {
  id: string;
  kind: TemplateKind;
  /** Rules cited by the template (CR 608.2c, 118.12a, ...). At least one is required. */
  cr: string[];
  pattern: string;
  /**
   * JSON to produce; strings "$hole" and "$hole.field" are substituted by captured values;
   * {"$when":"hole","then":X,"else":Y} chooses by presence of an optional hole;
   * {"$patchPrevious":{...}} merges fields into the previous step (riders such as "They can't be regenerated").
   * FAST5 T62: {"$concat":[X, Y, ...]} is one array of the arrays and items listed ("whenever A and whenever B": the events of both); a missing hole makes it missing.
   * Inside a "$patchPrevious" patch only (parser/lower/riders.ts, WP23; each fails closed: a reference that cannot be honored leaves the rider manual):
   *   "@previous" is a copy of the previous step, "@previous.a.b.0" the value at that path inside it (a missing path refuses the rider);
   *   {"@new": X} as a value sets that key only when the previous step does not have it (a second "Otherwise" is refused, never merged);
   *   "@replace": true at the top replaces the previous step by the patch instead of merging; it builds only "if C then [X] else [the previous step]"
   *   and only when X replaces that step as a whole (render/self-replacement.ts, CR 614.15).
   *   "@step": -n at the top (M6-8, opt-in) names the n-th top-level step from the end of the previous sentence instead of its last one.
   *   "@into": true at the top (FAST5 T45, opt-in) lets a rider whose `attachTo` op is not the previous step's own op reach the instruction inside a wrapper that only decides
   *   whether or when it happens: `may.do`, `pay.then`, `if.then`, `delay.do` (the last instruction of the branch; a wrapper with an else / otherwise is refused).
   *   "@byOp": {"<op>": {...}} at the top (r5-repl, opt-in) holds one patch per op `attachTo` lists; the one for the previous step's op is merged into the patch.
   *   "@require": {"a.b.0": value} at the top (FAST5 T56, opt-in) refuses the rider unless the previous step has that value at each dotted path (null: nothing there).
   *   "@oneOf": [patch, ...] at the top (std-exile-play-2-1, opt-in) lists patches for different shapes of the previous step, each with its own "@require"; the first
   *   whose "@require" holds is merged into the patch (none: the rider is refused). One wording, one template, several shapes of what it modifies.
   *   FAST5 T56: a rider that attaches to an op also modifies it where an "unless <player> pays" wrapper carries it out (a `pay` whose only `else` step has that op).
   * A parser older than WP23 would merge these markers literally: a rules pack that ships a template using them needs a parser of WP23 or later.
   * FAST5 T64 INTERFACE CHANGE (additive): `{"ref":"target","id":"","$target":{kind, min, max, text, filter?}}` is a target phrase the template spells out in its
   * own words (the marker the Obj hole writes, parser/holes/core.ts#targetRef), for a description no hole grammar reads ("up to one target creature on the
   * battlefield or creature card in a graveyard"); `text` must be those words exactly as the pattern has them. A rules pack that ships one needs a parser of T64 or later.
   * LOOK3 INTERFACE CHANGE (additive): `{"cond":"did","step":"","$step":"previous"}`, optionally with `"not": true` and `"to": "battlefield" | "hand"`, is the marker the
   * Cond hole writes for "you do" / "you don't" (parser/holes/cond.ts), for a condition the template spells out in its own words ("If you don't put the card onto the
   * battlefield, ...", zz-cloud/look3.json); parser/lower/conditions.ts#resolveDid names the step it reads. A rules pack that ships one needs a parser of LOOK3 or later.
   * Nothing else: no code, no expressions.
   */
  build: unknown;
  /** Effect/static templates: the sort of subject the pattern requires (prunes the search). */
  subject?: 'object' | 'player' | 'any' | 'none';
  /** Riders only: the op of the previous step the sentence attaches to (r4-repl, additive: or several, "createToken|copy", for the plain previous step; lower/riders.ts). */
  attachTo?: string;
  examples: TemplateExample[];
  /** Wordings that look similar but MUST NOT match, or must parse to different JSON (mutation tests, guard G9). At least two. */
  counterExamples: string[];
  /** Words of rules meaning that this template interprets itself (so the critical-word check G2 passes). */
  consumes?: string[];
  priority?: number;
  /**
   * CLOUD std-fra INTERFACE CHANGE (additive): a number of unspecific holes (as `Alt.weak`, design 6.3 rule 2) the template itself adds to every derivation that uses it: a
   * GENERIC template that reads a sentence only when no narrower template does ("Then <any instructions>", "<object> gains your choice of three keywords") has `weak: 1`, so a
   * derivation without it is preferred whatever JSON it has, and the generic one is never in an equal-priority conflict with a narrower template. Default 0.
   */
  weak?: number;
  /** `experimental` (fewer than 20 corpus matches and not yet reviewed): cards using it are capped at `partial` (design 6.9). */
  status: 'stable' | 'experimental';
  since: number;
  /** Capabilities the output needs; the template is skipped (the sentence stays manual with requiresEngine) on engines that lack them. */
  needs?: string[];
}

export interface LedgerEntry {
  /** Character range in the normalized text of the face. */
  range: [number, number];
  status: 'consumed' | 'reminder' | 'label' | 'structure' | 'manual';
  by?: string;
  reason?: string;
}

export type DiagnosticCode =
  | 'no-template' | 'unknown-word' | 'ambiguous' | 'critical-word' | 'leftover-text' | 'gate-mismatch' | 'unbound-reference'
  | 'needs-engine' | 'lint' | 'contagion' | 'poisoned' | 'budget' | 'parser-error' | 'unknown-keyword' | 'force-manual' | 'experimental';

export interface Diagnostic {
  level: 'info' | 'warning' | 'manual';
  code: DiagnosticCode;
  message: string;
  range?: [number, number];
  /** Furthest token the parser reached and the tokens it would have accepted there (LLM repair prompt, mining report). */
  furthest?: { token: string; expected: string[] };
  /** The lowered alternatives when code is 'ambiguous'. */
  alternatives?: unknown[];
}

export interface Lexicon {
  crEdition: string;
  cardTypes: string[];
  supertypes: string[];
  subtypes: { singular: string; plural: string; class: 'creature' | 'land' | 'artifact' | 'enchantment' | 'spell' | 'planeswalker' | 'battle' }[];
  colors: { word: string; color: string }[];
  keywordAbilities: { name: string; rule: string }[];
  keywordActions: { name: string; rule: string; forms: string[] }[];
  counterKinds: string[];
  predefinedTokens: { name: string; rule: string }[];
  abilityWords: string[];
}

export interface ParseOptions {
  templates: Template[];
  lexicon: Lexicon;
  /** `keyword:*`, `op:*` ... of the running engine; templates whose `needs` are missing are skipped. */
  capabilities: ReadonlySet<string>;
  /** Registered keyword names and parameter shapes (from KeywordRegistry). */
  keywords: {
    name: string; aliases: string[]; params: string[]; reminder: string;
    /**
     * FAST1 T4 ADDITION (INTERFACE CHANGE, optional): an implemented wrapper keyword ("Exhaust -- [Cost]: [Effect]", CR 702.177a): the restrictions it gives
     * the activated ability it is written before (the keyword data's `modifies`, keywords/types.ts#KeywordModifier).
     */
    wraps?: Pick<ActivatedAbilityDef, 'limit' | 'sorcerySpeed' | 'onlyIf' | 'zone' | 'reducedByManaCost'>;
    /**
     * FAST5X-4 ADDITION (INTERFACE CHANGE, optional): an implemented keyword that grants the ability after its dash while a condition holds ("Max speed --
     * [Ability]" is "As long as your speed is 4, this object has [Ability]", CR 702.178a): that condition (the keyword data's `modifies` of kind `grant`).
     */
    grants?: Condition;
  }[];
  /** All card names of the local index, for "named X" and self-reference of other cards. Optional. */
  cardNames?: ReadonlySet<string>;
  /** Hard limit on chart items per ability; exceeding it makes the ability manual with code 'budget'. */
  budget?: number;
}

export interface FaceParse {
  abilities: AbilityDef[];
  ledger: LedgerEntry[];
  diagnostics: Diagnostic[];
  /** Render-gate result per ability (same order as `abilities`). Empty for manual abilities. */
  gate: GateResult[];
  templatesUsed: string[];
  /** Ids of experimental templates that matched (they cap the card at partial). */
  experimental: string[];
  /**
   * W3b INTERFACE ADDITION: per ability (same order as `abilities`), the experimental templates its lowering used. The pipeline drops an experimental
   * template from the card's cap when every ability that used it was replaced by a gated, fully automated reading of another source (cards/pipeline.ts,
   * native stage). Absent: unknown (every ability counts as having used all of `experimental`).
   */
  experimentalBy?: string[][];
}

export interface ParseResult {
  faces: FaceParse[];
  parserVersion: string;
}

/** Never throws: an exception inside a face becomes one manual ability with diagnostic 'parser-error' (contract C1). */
export type ParseCard = (card: OracleCard, opts: ParseOptions) => ParseResult;
